const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function text(value) {
  return String(value ?? '').trim();
}

function normalizedKey(value) {
  return text(value).toLowerCase().replace(/[^a-z0-9]/g, '');
}

function read(row, ...names) {
  const entries = Object.entries(row || {});
  const wanted = names.map(normalizedKey);
  for (const name of wanted) {
    const exact = entries.find(([key, value]) => normalizedKey(key) === name && value !== null && value !== undefined);
    if (exact) return exact[1];
  }
  for (const name of wanted) {
    const partial = entries.find(([key, value]) => {
      const candidate = normalizedKey(key);
      return value !== null && value !== undefined && (candidate.includes(name) || name.includes(candidate));
    });
    if (partial) return partial[1];
  }
  return '';
}

function findEmail(row) {
  for (const value of Object.values(row || {})) {
    const candidate = text(value).toLowerCase();
    if (EMAIL_RE.test(candidate)) return candidate;
  }
  return '';
}

function field(row, columnIndex, ...names) {
  const named = read(row, ...names);
  if (text(named)) return named;
  return row && Object.prototype.hasOwnProperty.call(row, 'col_' + columnIndex)
    ? row['col_' + columnIndex]
    : '';
}

function amount(value) {
  const parsed = Number(text(value).replace(/[$,\s]/g, ''));
  return Number.isFinite(parsed) ? parsed : null;
}

function contractStatus(value) {
  const status = text(value).toLowerCase();
  if (/complete|signed|yes/.test(status)) return 'signed';
  if (/sent|shared/.test(status)) return 'sent';
  if (/not|pending/.test(status)) return 'not_signed';
  return null;
}

function paymentStatus(value) {
  const status = text(value).toLowerCase();
  if (/sent|paid|disbursed/.test(status)) return 'disbursed';
  if (/process|pending/.test(status)) return 'processing';
  if (/reject|fail/.test(status)) return 'failed';
  return status || 'pending';
}

function pad(value) {
  return String(value).padStart(2, '0');
}

function isoDate(value) {
  const raw = text(value);
  if (!raw) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;

  const named = raw.match(/^(\d{1,2})[\s-]([A-Za-z]{3,9})[\s,.-]+(\d{4})$/);
  if (named) {
    const month = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 }[named[2].slice(0, 3).toLowerCase()];
    return month ? named[3] + '-' + pad(month) + '-' + pad(named[1]) : null;
  }

  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime())
    ? null
    : parsed.getFullYear() + '-' + pad(parsed.getMonth() + 1) + '-' + pad(parsed.getDate());
}

const output = [];

for (const item of items) {
  const row = item.json;
  const email = (text(field(row, 1, 'Email Id', 'Email')) || findEmail(row)).toLowerCase();
  if (!EMAIL_RE.test(email)) continue;

  const taskRate = amount(field(row, 8, 'Candidates Rate Task - USD', 'Candidate Rate -Task'));
  const reviewRate = amount(field(row, 11, 'Candidates Rate USD', 'Candidate Rate - Review'));
  const finalAmount = amount(field(row, 16, 'Final Amt', 'Final Amount'));

  output.push({
    json: {
      p_email: email,
      p_full_name: text(field(row, 2, 'Name')) || null,
      p_contract_status: contractStatus(field(row, 5, 'Contract Status', 'Contract status')), 
      p_task_rate_amount: taskRate,
      p_review_rate_amount: reviewRate,
      p_currency: 'USD',
      p_payment_amount: finalAmount,
      p_payment_currency: 'INR',
      p_payment_status: paymentStatus(field(row, 17, 'Payment Status', 'Status')), 
      p_paid_on: isoDate(field(row, 18, 'Amount Sent Date')),
      p_period_start: '2026-07-01',
      p_period_end: '2026-07-31',
      p_payment_reference: 'Mojave / July 2026',
      p_source_sheet: 'SnorkelxMojave - Sub Contracting Payment / July - 2026',
    },
  });
}

return output;
